/**
 * Official Factorial API client.
 *
 * @example
 * ```ts
 * import { FactorialClient } from "@factorial/api-client";
 *
 * const client = new FactorialClient({
 *   apiKey: process.env.FACTORIAL_API_KEY,
 * });
 *
 * // List employees (single page, max 100)
 * const { data } = await client.employees.employees.list();
 *
 * // Stream all employees across all pages (cursor pagination)
 * for await (const employee of client.employees.employees.paginate()) {
 *   console.log(employee.full_name);
 * }
 *
 * // Collect all into an array (with optional safety cap)
 * const all = await client.employees.employees.all({ maxItems: 500 });
 * ```
 */
export class FactorialClient {
  /** ApiPublic resources */
  readonly apiPublic: ApiPublicNamespace;
  /** Approvals resources */
  readonly approvals: ApprovalsNamespace;
  /** Ats resources */
  readonly ats: AtsNamespace;
  /** Attendance resources */
  readonly attendance: AttendanceNamespace;
  /** Banking resources */
  readonly banking: BankingNamespace;
  /** BookkeepersManagement resources */
  readonly bookkeepersManagement: BookkeepersManagementNamespace;
  /** Companies resources */
  readonly companies: CompaniesNamespace;
  /** Compensations resources */
  readonly compensations: CompensationsNamespace;
  /** Contracts resources */
  readonly contracts: ContractsNamespace;
  /** CustomFields resources */
  readonly customFields: CustomFieldsNamespace;
  /** CustomResources resources */
  readonly customResources: CustomResourcesNamespace;
  /** Documents resources */
  readonly documents: DocumentsNamespace;
  /** EmployeeUpdates resources */
  readonly employeeUpdates: EmployeeUpdatesNamespace;
  /** Employees resources */
  readonly employees: EmployeesNamespace;
  /** Expenses resources */
  readonly expenses: ExpensesNamespace;
  /** Finance resources */
  readonly finance: FinanceNamespace;
  /** Holidays resources */
  readonly holidays: HolidaysNamespace;
  /** Integrations resources */
  readonly integrations: IntegrationsNamespace;
  /** ItManagement resources */
  readonly itManagement: ItManagementNamespace;
  /** JobCatalog resources */
  readonly jobCatalog: JobCatalogNamespace;
  /** Locations resources */
  readonly locations: LocationsNamespace;
  /** Marketplace resources */
  readonly marketplace: MarketplaceNamespace;
  /** Payroll resources */
  readonly payroll: PayrollNamespace;
  /** PayrollEmployees resources */
  readonly payrollEmployees: PayrollEmployeesNamespace;
  /** PayrollIntegrationsBase resources */
  readonly payrollIntegrationsBase: PayrollIntegrationsBaseNamespace;
  /** Performance resources */
  readonly performance: PerformanceNamespace;
  /** Posts resources */
  readonly posts: PostsNamespace;
  /** Procurement resources */
  readonly procurement: ProcurementNamespace;
  /** ProjectManagement resources */
  readonly projectManagement: ProjectManagementNamespace;
  /** ShiftManagement resources */
  readonly shiftManagement: ShiftManagementNamespace;
  /** Tasks resources */
  readonly tasks: TasksNamespace;
  /** Teams resources */
  readonly teams: TeamsNamespace;
  /** TimePlanning resources */
  readonly timePlanning: TimePlanningNamespace;
  /** TimeSettings resources */
  readonly timeSettings: TimeSettingsNamespace;
  /** Timeoff resources */
  readonly timeoff: TimeoffNamespace;
  /** Trainings resources */
  readonly trainings: TrainingsNamespace;
  /** WorkSchedule resources */
  readonly workSchedule: WorkScheduleNamespace;

  constructor(config: FactorialClientConfig = {}) {
    const { apiKey, token, baseUrl, ...rest } = config;

    if (!apiKey && !token) {
      throw new Error("FactorialClient: provide either apiKey or token");
    }

    // hey-api calls the auth callback once per security scheme in spec order:
    // 1. { type: 'http', scheme: 'bearer' }  → Authorization: Bearer <token>
    // 2. { type: 'apiKey', name: 'x-api-key' } → x-api-key: <key>
    // Return a value only for the matching scheme so the other is skipped.
    const auth = (scheme: { type: string }) => {
      if (scheme.type === "http") return token;       // OAuth bearer
      if (scheme.type === "apiKey") return apiKey;    // API key
      return undefined;
    };

    const client = createClient(
      createConfig<ClientOptions>({
        baseUrl: baseUrl ?? "https://api.factorialhr.com",
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        auth: auth as any,
        ...(rest as any),
      })
    );
    this.apiPublic = new ApiPublicNamespace(client);
    this.approvals = new ApprovalsNamespace(client);
    this.ats = new AtsNamespace(client);
    this.attendance = new AttendanceNamespace(client);
    this.banking = new BankingNamespace(client);
    this.bookkeepersManagement = new BookkeepersManagementNamespace(client);
    this.companies = new CompaniesNamespace(client);
    this.compensations = new CompensationsNamespace(client);
    this.contracts = new ContractsNamespace(client);
    this.customFields = new CustomFieldsNamespace(client);
    this.customResources = new CustomResourcesNamespace(client);
    this.documents = new DocumentsNamespace(client);
    this.employeeUpdates = new EmployeeUpdatesNamespace(client);
    this.employees = new EmployeesNamespace(client);
    this.expenses = new ExpensesNamespace(client);
    this.finance = new FinanceNamespace(client);
    this.holidays = new HolidaysNamespace(client);
    this.integrations = new IntegrationsNamespace(client);
    this.itManagement = new ItManagementNamespace(client);
    this.jobCatalog = new JobCatalogNamespace(client);
    this.locations = new LocationsNamespace(client);
    this.marketplace = new MarketplaceNamespace(client);
    this.payroll = new PayrollNamespace(client);
    this.payrollEmployees = new PayrollEmployeesNamespace(client);
    this.payrollIntegrationsBase = new PayrollIntegrationsBaseNamespace(client);
    this.performance = new PerformanceNamespace(client);
    this.posts = new PostsNamespace(client);
    this.procurement = new ProcurementNamespace(client);
    this.projectManagement = new ProjectManagementNamespace(client);
    this.shiftManagement = new ShiftManagementNamespace(client);
    this.tasks = new TasksNamespace(client);
    this.teams = new TeamsNamespace(client);
    this.timePlanning = new TimePlanningNamespace(client);
    this.timeSettings = new TimeSettingsNamespace(client);
    this.timeoff = new TimeoffNamespace(client);
    this.trainings = new TrainingsNamespace(client);
    this.workSchedule = new WorkScheduleNamespace(client);
  }
}
